    client.once('error', (error) => {
      clearTimeout(timeout)
      reject(error)
    })
    client.once('open', () => {
      for (const payload of payloads) client.send(JSON.stringify(payload))
      if (!firstMessage) setTimeout(() => finish('Sent'), 300)
