        )
        if (name === 'simulator_text')
          return text(
            await post('/api/previews/simulator/input', {
              taskId: task,
              id: opened.id,
              input: { type: 'text', text: string(input.value, 'value') },
            }),
          )
        if (name === 'simulator_key' || name === 'simulator_button')
          return text(
            await post('/api/previews/simulator/input', {
              taskId: task,
              id: opened.id,
              input:
                name === 'simulator_key'
