import { decode, workflowCommandSchema } from '@dovo/protocol/agent-tools';
/** Accept encoded plan metadata without changing the canonical plan command. */
export function workflowCommand(input) {
    let phases = input.phases;
    if (typeof phases === 'string') {
        try {
            phases = JSON.parse(phases);
        }
        catch (cause) {
            throw new Error('Workflow phases must contain a valid JSON array.', { cause });
        }
    }
    return decode(workflowCommandSchema, {
        ...input,
        ...(phases === undefined ? {} : { phases }),
    });
}

source.terminal-input-command.js:
/** Preserve raw terminal data. Submission appends one actual carriage return. */
export function terminalInputData(input) {
    if (typeof input.data !== 'string')
        throw new Error('Expected terminal data to be a string');
    if (input.submit !== undefined && typeof input.submit !== 'boolean')
        throw new Error('Expected terminal submit to be a boolean');
    return input.data + (input.submit === true ? '\r' : '');
}

