      { id: 'android:emulator', ...coordinates, startX: -1 },
      { id: 'android:emulator', ...coordinates, endY: 3841 },
      { id: 'android:emulator', startX: 100, startY: 100, endX: 200 },
      { id: 'not-a-device', ...coordinates },
    ]) {
