it.each(['ask', 'read-only'] as const)(
  'launches and receives a cross-harness child through run-scoped MCP (%s)',
  async (permission) => {
    const f = await fixture()
    const token = 'task-tools-owner-token-at-least-thirty-two-characters'
    const runtime = await startRuntime({ databasePath: ':memory:', ownerToken: token, port: 0 })
    try {
      const s = runtime.services
      s.store.update(() => ({
        ...f.workspace,
        agents: f.workspace.agents.map((agent) => ({ ...agent, permission })),
      }))
      vi.spyOn(s.agents, 'get').mockResolvedValue({
        probe: vi.fn<AgentAdapter['probe']>(),
        run: async (run) => {
          if (run.agent.provider === 'claude') {
            run.onText('Answer from Claude')
            return
          }
          if (!run.taskId) throw new Error('Expected a parent task')
          const configuration = run.agent.resources?.mcpServers.find(
            (server) => server.name === 'dovo_task',
          )
          if (!configuration) throw new Error('Expected the run-scoped task tools')
          expect(configuration.envValues?.DOVO_TASK_TOKEN).toBeUndefined()
          expect(configuration.envValues?.DOVO_TASK_CREDENTIAL_FILE).toBeTruthy()
          const client = new Client({ name: 'parent-tools-test', version: '1.0.0' })
          const transport = new StdioClientTransport({
            command: configuration.command,
            args: configuration.args,
            env: { ...configuration.envValues },
            stderr: 'ignore',
          })
          try {
            await client.connect(transport)
            const plan = {
              action: 'create',
              id: 'review-flow',
              name: 'Review changes',
              phases: [{ id: 'inspect', title: 'Inspect' }],
            }
            const created = await client.callTool({ name: 'workflow', arguments: plan })
            expect(created.isError).not.toBe(true)
            expect(
              (
                await client.callTool({
                  name: 'workflow',
                  arguments: { ...plan, taskId: 'forged-parent' },
                })
              ).isError,
            ).toBe(true)
            expect(
              (
                await client.callTool({
                  name: 'workflow',
                  arguments: {
                    ...plan,
                    id: 'duplicate-phases',
                    phases: [plan.phases[0], plan.phases[0]],
                  },
                })
              ).isError,
            ).toBe(true)
            expect(JSON.parse(decodeToolText(created))).toMatchObject({
              id: 'review-flow',
              state: 'queued',
            })
            expect((await client.callTool({ name: 'workflow', arguments: plan })).isError).not.toBe(
              true,
            )
            expect(
              (
                await client.callTool({
                  name: 'workflow',
                  arguments: { ...plan, name: 'Changed plan' },
                })
              ).isError,
            ).toBe(true)
            const arguments_ = {
              key: 'review',
              name: 'Review',
              prompt: 'Review current files',
              provider: 'claude',
            }
            for (const extra of [
              { permissions: 'read-only' },
              { taskId: 'forged-parent', parentRunId: 'forged-attempt' },
            ]) {
              const rejected = await client.callTool({
                name: 'subagent_spawn',
                arguments: { ...arguments_, ...extra },
              })
              expect(rejected.isError).toBe(true)
              expect(s.store.get().tasks).toHaveLength(1)
            }
            const spawned = await client.callTool({
              name: 'subagent_spawn',
              arguments: arguments_,
            })
            const { id } = decode(
              mutableStruct({ id: Schema.String }),
              JSON.parse(decodeToolText(spawned)),
            )
            const membership = {
              action: 'attach',
              id: 'review-flow',
              phaseId: 'inspect',
              childId: id,
            }
            expect(
              (await client.callTool({ name: 'workflow', arguments: membership })).isError,
            ).not.toBe(true)
            expect(
              (await client.callTool({ name: 'workflow', arguments: membership })).isError,
            ).not.toBe(true)
            expect(
              (
                await client.callTool({
                  name: 'workflow',
                  arguments: { ...membership, childId: run.taskId },
                })
              ).isError,
            ).toBe(true)
            expect(
              (
                await client.callTool({
                  name: 'workflow',
                  arguments: { ...membership, phaseId: 'missing' },
                })
              ).isError,
            ).toBe(true)
            expect(s.store.task(run.taskId).workflows?.[0]?.members).toHaveLength(1)
            expect(s.store.task(id).delegation?.parentTaskId).toBe(run.taskId)
            expect(s.store.task(id).harness?.permission).toBe(permission)
            const waited = await client.callTool({
              name: 'subagent_wait',
              arguments: { id, timeoutMs: 20000 },
            })
            expect(JSON.parse(decodeToolText(waited))).toMatchObject({
              id,
              running: false,
              status: 'review',
              result: 'Answer from Claude',
            })
            const workflow = await client.callTool({
              name: 'workflow',
              arguments: { action: 'read', id: 'review-flow' },
            })
            expect(JSON.parse(decodeToolText(workflow))).toMatchObject({
              state: 'completed',
              phases: [
                {
                  id: 'inspect',
                  state: 'completed',
                  members: [{ id, provider: 'claude', state: 'completed' }],
                },
              ],
            })
            const list = await client.callTool({ name: 'subagent_list', arguments: {} })
            expect(JSON.parse(decodeToolText(list))).toMatchObject({
              agents: [{ id, status: 'review' }],
            })
            run.onText('Received the child answer')
          } finally {
            await client.close()
            await transport.close()
          }
        },
      })
      const parent = s.tasks.create({
        title: 'Parent',
        repositoryId: 'repo',
        agentId: 'agent',
        objective: 'Delegate review',
      })
      await (
        await s.tasks.start(parent.id)
      ).done
      expect(s.store.task(parent.id).status).toBe('review')
    } finally {
      await runtime.close()
      await f.cleanup()
    }
  },
  30000,
)

