      (
        await client.callTool({
          name: 'terminal_rename',
          arguments: { id: user.id, title: 'Forbidden' },
        })
      ).isError,
    ).toBe(true)
    expect(
      (await client.callTool({ name: 'terminal_rename', arguments: { id, title: '   ' } })).isError,
    ).toBe(true)
    expect(s.terminals.get(id).info.title).toBe('Build server')
    expect(
      (await client.callTool({ name: 'terminal_rename', arguments: { id, title: '  Tests  ' } }))
        .isError,
    ).not.toBe(true)
    expect(s.terminals.get(id).info).toMatchObject({ title: 'Tests', customTitle: 'Tests' })
    expect(
      (await client.callTool({ name: 'terminal_rename', arguments: { id, title: null } })).isError,
    ).not.toBe(true)
    expect(s.terminals.get(id).info.customTitle).toBeUndefined()
    expect(s.terminals.get(id).info.title).not.toBe('Tests')
    expect(s.terminals.get(id).process).toBe(terminalProcess)
    expect(input).toHaveBeenCalledTimes(1)
    expect(input).toHaveBeenCalledWith(id, 'printf tool-output\r')
    expect(
      (
        await client.callTool({
          name: 'terminal_input',
          arguments: { id, data: 'printf submitted', submit: true },
        })
      ).isError,
    ).not.toBe(true)
    expect(input).toHaveBeenLastCalledWith(id, 'printf submitted\r')
    expect(
      (await client.callTool({ name: 'terminal_input', arguments: { id, data: 'raw\\r' } }))
        .isError,
    ).not.toBe(true)
    expect(input).toHaveBeenLastCalledWith(id, 'raw\\r')
    const beforeInput = input.mock.calls.length
    for (const arguments_ of [
      { id, data: 'bad', submit: 'true' },
      { id: user.id, data: 'forbidden', submit: true },
    ])
      expect(
        (await client.callTool({ name: 'terminal_input', arguments: arguments_ })).isError,
      ).toBe(true)
    expect(input).toHaveBeenCalledTimes(beforeInput)
    expect(input.mock.calls.every(([target]) => target === id)).toBe(true)
    const command = s.activity
      .list('', 'task-activity', 0, task.id)
      .events.find((event) => event.summary === 'Terminal command')
    expect(command).toBeDefined()
    expect(JSON.parse(command!.payload)).toMatchObject({
      terminalCommand: true,
      presentation: { kind: 'command', input: 'printf tool-output' },
    })
    expect(
      (await client.callTool({ name: 'terminal_close', arguments: { id: user.id } })).isError,
    ).toBe(true)
    expect((await client.callTool({ name: 'terminal_close', arguments: { id } })).isError).not.toBe(
      true,
    )
    expect(s.terminals.list().map((terminal) => terminal.id)).toEqual([user.id])
    expect(
      (await client.callTool({ name: 'terminal_rename', arguments: { id, title: 'Closed' } }))
        .isError,
    ).toBe(true)
  } finally {
    await client.close()
    await transport?.close()
    await runtime.close()
    await f.cleanup()
  }
}, 15000)

