  tools: enabledTools.map((tool) => ({
    ...tool,
    inputSchema:
      process.env.DOVO_TASK_SCHEMA_PROFILE === 'muse'
        ? { ...museToolSchema(tool.inputSchema), type: 'object' as const }
        : tool.inputSchema,
  })),
}))
await server.connect(new StdioServerTransport())

